-- Seed: Indicadores de 3ro de Secundaria - Lengua Española

INSERT INTO public.curr_indicadores (grado, asignatura, competencia, codigo, descripcion) VALUES
-- BC1
('3ro', 'Lengua Española', 'BC1', 'IL-1', 'Se desenvuelve de forma oral o escrita mediante un género textual con eficacia y creatividad en diferentes situaciones de comunicación de la vida social, de manera directa o haciendo uso de herramientas tecnológicas.'),
('3ro', 'Lengua Española', 'BC1', 'IL-2', 'Utiliza de manera responsable variadas herramientas tecnológicas, en sus relaciones con compañeros, familiares y sociedad en general, para una comunicación oral o escrita efectiva en los diferentes contextos que participa.'),
('3ro', 'Lengua Española', 'BC1', 'IL-3', 'Emplea textos sobre situaciones de la realidad local, nacional y del mundo, comunicando eficazmente sus ideas, pensamientos, propuestas y acciones de forma crítica y creativa.'),

-- BC2
('3ro', 'Lengua Española', 'BC2', 'IL-4', 'Reconoce y utiliza de manera lógica las secuencias argumentativas, en la presentación de discursos sobre temas sociales del contexto local y nacional.'),
('3ro', 'Lengua Española', 'BC2', 'IL-5', 'Emplea textos diversos que ponen de relieve situaciones del entorno escolar, familiar, comunitario, nacional y del mundo, promoviendo nuevos conocimientos inferenciales derivados de la comprensión de la realidad.'),
('3ro', 'Lengua Española', 'BC2', 'IL-6', 'Expone a través de tipos de textos y en actos de intercomunicación, sus juicios, puntos de vista, conclusiones, bajo un marco de respeto en las diversas opiniones y con miras a la acción.'),
('3ro', 'Lengua Española', 'BC2', 'IL-7', 'Investiga sobre problemas o conflictos relacionados con su vida estudiantil, familiar o social en general, empleando la tipología textual adecuada, con miras a comprender y buscar posibles soluciones.'),
('3ro', 'Lengua Española', 'BC2', 'IL-8', 'Redacta textos con información confiable que apoyan la solución de problemas o conflictos de su entorno comunitario y fuera de este.'),
('3ro', 'Lengua Española', 'BC2', 'IL-9', 'Presenta conclusiones y recomendaciones, producto de estudios realizados, que orientan la solución de problemas, haciendo uso de textos como ensayos, informes u otros tipos convenientes.'),

-- BC3
('3ro', 'Lengua Española', 'BC3', 'IL-13', 'Demuestra conocimientos científicos y tecnológicos a través de la producción textual y el uso de plataformas o herramientas digitales convenientes, poniendo en práctica saberes de acuerdo con su nivel.'),
('3ro', 'Lengua Española', 'BC3', 'IL-14', 'Utiliza textos de secuencia expositivo-explicativa en la divulgación de hallazgos científicos y sociales de diferentes contextos, en demostración de dominio de la lengua y conocimiento sobre investigación.'),
('3ro', 'Lengua Española', 'BC3', 'IL-15', 'Publica investigaciones científicas sencillas en actividades escolares, comunitarias, con apoyo de herramientas tecnológicas, en demostración de dominio de procesos investigativos sencillos y el uso de textos expositivo-explicativos.'),
('3ro', 'Lengua Española', 'BC3', 'IL-16', 'Estudia temas o problemas sobre salud, medioambiente, alimentación, entre otros que afectan la comunidad nacional y mundial, mediante textos variados y apoyándose en herramientas tecnológicas y otros medios y recursos.'),
('3ro', 'Lengua Española', 'BC3', 'IL-17', 'Elabora textos como el catálogo, recetas, artículos de opinión, instructivos, entre otros, en la promoción de situaciones sobre salud y ambiente, flora y fauna dominicanas y en general.'),
('3ro', 'Lengua Española', 'BC3', 'IL-18', 'Difunde nuevos conocimientos, comportamientos y valores sobre la conservación de la salud, el cuidado de la naturaleza y sus ecosistemas, en actividades de intercomunicación y haciendo uso de textos diversos para su conocimiento y puesta en práctica.'),

-- BC4
('3ro', 'Lengua Española', 'BC4', 'IL-10', 'Promueve nuevas relaciones sociales del ámbito nacional e internacional a través de un género textual conveniente, reconociendo y valorando lo natural y sociocultural de los contextos.'),
('3ro', 'Lengua Española', 'BC4', 'IL-11', 'Cuestiona prácticas sociales de ciudadanía en el entorno local, nacional, en confrontación con los valores universales, mediante producciones textuales diversas.'),
('3ro', 'Lengua Española', 'BC4', 'IL-12', 'Utiliza textos convenientes en la elaboración de proyectos variados sobre ciudadanía, con miras a la solución de problemas que afectan la sociedad que lo rodea y fuera de ella.'),
('3ro', 'Lengua Española', 'BC4', 'IL-19', 'Demuestra su compromiso consigo mismo y con los demás, en atención a las situaciones que se presentan en contexto social, a través de tipos de textos convenientes.'),
('3ro', 'Lengua Española', 'BC4', 'IL-20', 'Cultiva valores universales y refuerza la dimensión humanista, mediante la producción oral y escrita de textos funcionales y literarios, en la promoción del desarrollo espiritual y físico suyo y de los demás.'),
('3ro', 'Lengua Española', 'BC4', 'IL-21', 'Promueve emociones, sentimientos, valores espirituales mediante lecturas y escrituras reflexivas, en defensa del respeto, la dignidad y las relaciones entre las personas.');
